@Test
public void testReplace() throws Exception {
    assertThat(StringUtils.replace(null, "*", "*"), nullValue());
    assertThat(StringUtils.replace("", "*", "*"), equalTo(""));
    assertThat(StringUtils.replace("any", null, "*"), equalTo("any"));
