@Test
public void testGetInstances() {
    List<ServiceInstance> instances = asList(new DefaultServiceInstance("A", "127.0.0.1", 8080), new DefaultServiceInstance("A", "127.0.0.1", 8081), new DefaultServiceInstance("A", "127.0.0.1", 8082));
    instances.forEach(serviceDiscovery::register);
    // Duplicated
    serviceDiscovery.register(new DefaultServiceInstance("A", "127.0.0.1", 8080));
    // Duplicated
    serviceDiscovery.register(new DefaultServiceInstance("A", "127.0.0.1", 8081));
    // offset starts 0
    int offset = 0;
    // pageSize > total elements
    int pageSize = 5;
    Page<ServiceInstance> page = serviceDiscovery.getInstances("A", offset, pageSize);
    assertEquals(0, page.getOffset());
    assertEquals(5, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(3, page.getData().size());
    assertTrue(page.hasData());
    for (ServiceInstance instance : page.getData()) {
        assertTrue(instances.contains(instance));
    }
    // pageSize < total elements
    pageSize = 2;
    page = serviceDiscovery.getInstances("A", offset, pageSize);
    assertEquals(0, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(2, page.getData().size());
    assertTrue(page.hasData());
    for (ServiceInstance instance : page.getData()) {
        assertTrue(instances.contains(instance));
    }
    offset = 1;
    page = serviceDiscovery.getInstances("A", offset, pageSize);
    assertEquals(1, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(2, page.getData().size());
    assertTrue(page.hasData());
    for (ServiceInstance instance : page.getData()) {
        assertTrue(instances.contains(instance));
    }
    offset = 2;
    page = serviceDiscovery.getInstances("A", offset, pageSize);
    assertEquals(2, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(1, page.getData().size());
    assertTrue(page.hasData());
    offset = 3;
    page = serviceDiscovery.getInstances("A", offset, pageSize);
    assertEquals(3, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(0, page.getData().size());
    assertFalse(page.hasData());
    offset = 5;
    page = serviceDiscovery.getInstances("A", offset, pageSize);
    assertEquals(5, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(0, page.getData().size());
    assertFalse(page.hasData());
}

@Test
public void testGetInstancesWithHealthy() {
    List<ServiceInstance> instances = new LinkedList<>(asList(new DefaultServiceInstance("A", "127.0.0.1", 8080), new DefaultServiceInstance("A", "127.0.0.1", 8081)));
    DefaultServiceInstance serviceInstance = new DefaultServiceInstance("A", "127.0.0.1", 8082);
    serviceInstance.setHealthy(false);
    instances.add(serviceInstance);
    instances.forEach(serviceDiscovery::register);
    // offset starts 0
    int offset = 0;
    // requestSize > total elements
    int requestSize = 5;
    Page<ServiceInstance> page = serviceDiscovery.getInstances("A", offset, requestSize, true);
    assertEquals(0, page.getOffset());
    assertEquals(5, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(2, page.getData().size());
    assertTrue(page.hasData());
    for (ServiceInstance instance : page.getData()) {
        assertTrue(instances.contains(instance));
    }
    // requestSize < total elements
    requestSize = 2;
    offset = 1;
    page = serviceDiscovery.getInstances("A", offset, requestSize, true);
    assertEquals(1, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(1, page.getData().size());
    assertTrue(page.hasData());
    for (ServiceInstance instance : page.getData()) {
        assertTrue(instances.contains(instance));
    }
    offset = 2;
    page = serviceDiscovery.getInstances("A", offset, requestSize, true);
    assertEquals(2, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(0, page.getData().size());
    assertFalse(page.hasData());
    offset = 3;
    page = serviceDiscovery.getInstances("A", offset, requestSize, true);
    assertEquals(3, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(0, page.getData().size());
    assertFalse(page.hasData());
    offset = 5;
    page = serviceDiscovery.getInstances("A", offset, requestSize, true);
    assertEquals(5, page.getOffset());
    assertEquals(2, page.getPageSize());
    assertEquals(3, page.getTotalSize());
    assertEquals(0, page.getData().size());
    assertFalse(page.hasData());
}

@Test
public void testRegistry() {
    // read server info from property
    if (PerformanceUtils.getProperty("server", null) == null) {
        logger.warn("Please set -Dserver=127.0.0.1:9090");
        return;
    }
    final int base = PerformanceUtils.getIntProperty("base", 0);
    final int concurrent = PerformanceUtils.getIntProperty("concurrent", 100);
    int r = PerformanceUtils.getIntProperty("runs", 1000);
    final int runs = r > 0 ? r : Integer.MAX_VALUE;
    final Registry registry = ExtensionLoader.getExtensionLoader(RegistryFactory.class).getAdaptiveExtension().getRegistry(URL.valueOf("remote://admin:hello1234@" + PerformanceUtils.getProperty("server", "10.20.153.28:9090")));
    for (int i = 0; i < concurrent; i++) {
        final int t = i;
        new Thread(new Runnable() {

            public void run() {
                for (int j = 0; j < runs; j++) {
                    registry.register(URL.valueOf("remote://" + NetUtils.getLocalHost() + ":8080/demoService" + t + "_" + j + "?version=1.0.0&application=demo&dubbo=2.0&interface=" + "org.apache.dubbo.demo.DemoService" + (base + t) + "_" + (base + j)));
                }
            }
        }).start();
    }
    synchronized (PerformanceRegistryTest.class) {
        while (true) {
            try {
                PerformanceRegistryTest.class.wait();
            } catch (InterruptedException e) {
            }
        }
    }
}

@Test
public void test() throws Exception {
    RegistryServiceListener listener1 = Mockito.mock(RegistryServiceListener.class);
    RegistryServiceListener1.delegate = listener1;
    RegistryServiceListener listener2 = Mockito.mock(RegistryServiceListener.class);
    RegistryServiceListener2.delegate = listener2;
    Registry registry = registryFactory.getRegistry(URL.valueOf("simple://localhost:8080/registry-service"));
    URL url = URL.valueOf("dubbo://localhost:8081/simple.service");
    registry.register(url);
    Mockito.verify(listener1, Mockito.times(1)).onRegister(url);
    Mockito.verify(listener2, Mockito.times(1)).onRegister(url);
    registry.unregister(url);
    Mockito.verify(listener1, Mockito.times(1)).onUnregister(url);
    Mockito.verify(listener2, Mockito.times(1)).onUnregister(url);
    registry.subscribe(url, Mockito.mock(NotifyListener.class));
    Mockito.verify(listener1, Mockito.times(1)).onSubscribe(url);
    Mockito.verify(listener2, Mockito.times(1)).onSubscribe(url);
    registry.unsubscribe(url, Mockito.mock(NotifyListener.class));
    Mockito.verify(listener1, Mockito.times(1)).onUnsubscribe(url);
    Mockito.verify(listener2, Mockito.times(1)).onUnsubscribe(url);
}

